let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
const cursorBot=document.querySelector('.cursor-bot'),botMotion=matchMedia('(prefers-reduced-motion: reduce)'),firstBotEye=cursorBot.querySelector('.cursor-bot-face i');
let botIdleTimer,botPointerInside=true,botFocused=true,lastBotPointer=null;
const restBot=()=>{for(const name of ['--bot-rx','--bot-ry','--bot-rz','--bot-x','--bot-y','--bot-slant','--eye-depth'])cursorBot.style.removeProperty(name);};
const canBotBlink=()=>document.body.dataset.screen==='home'&&!document.hidden&&!botMotion.matches&&botPointerInside&&botFocused;
const stopBotBlink=()=>{clearTimeout(botIdleTimer);cursorBot.classList.remove('is-blinking');};
